from itertools import product

def count_configs(q):
    """Count (lie_pos, silence_pos) configurations: lie in {None,1..q}, silence in {None,1..q}, lie != silence."""
    count = 0
    for lie in [None] + list(range(1,q+1)):
        for sil in [None] + list(range(1,q+1)):
            if lie != sil:  # can't lie and be silent on same round
                count += 1
    return count

def count_transcripts(q):
    """Count sequences of length q over {Y,N,*} with at most one *."""
